query issueEventsAndAssociatedObjectsByTechnicalBreakdown(
  $details: IssueDetails!
  $dimension: TechnicalBreakdownDimension!
) {
  issueEventsAndAssociatedObjectsByTechnicalBreakdown(
    details: $details
    dimension: $dimension
  ) {
    label
    items {
      label
      value
    }
  }
}
